import{_ as e,o as d,c as a,a3 as r}from"./chunks/framework.BlfGB29P.js";const _=JSON.parse('{"title":"Node、Edge 与静态托管","description":"","frontmatter":{"title":"Node、Edge 与静态托管","outline":[2,3],"article":{"type":"decision","structure":"decision"}},"headers":[],"relativePath":"frontend/decisions/rendering/edge-rendering.md","filePath":"frontend/decisions/rendering/edge-rendering.md","lastUpdated":1785589115000}'),i={name:"frontend/decisions/rendering/edge-rendering.md"};function o(l,t,n,s,h,c){return d(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="node、edge-与静态托管" tabindex="-1">Node、Edge 与静态托管 <a class="header-anchor" href="#node、edge-与静态托管" aria-label="Permalink to &quot;Node、Edge 与静态托管&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>页面选择 SSR 后，仍需决定代码在哪里运行；选择 SSG 或 CSR 后，也要决定静态制品如何托管。静态 CDN、中心区域 Node.js、Serverless 函数和 Edge Runtime 是不同运行与部署形态，可以在同一应用中组合。</p><h2 id="_1-决策背景" tabindex="-1">1. 决策背景 <a class="header-anchor" href="#_1-决策背景" aria-label="Permalink to &quot;1. 决策背景&quot;">​</a></h2><p>“Edge 一定更快”忽略了数据通常位于中心数据库，“Node 功能最全”也不代表所有请求都值得进入长驻服务。端到端延迟由用户到计算、计算到数据源、冷启动、缓存和响应体共同决定。</p><p>本章比较运行位置和责任模型，不重复页面该用 CSR、SSR 还是 SSG；先完成<a href="/frontend/decisions/rendering/rendering-strategy">页面渲染策略</a>，再选择部署形态。</p><h2 id="_2-硬约束与评价标准" tabindex="-1">2. 硬约束与评价标准 <a class="header-anchor" href="#_2-硬约束与评价标准" aria-label="Permalink to &quot;2. 硬约束与评价标准&quot;">​</a></h2><h3 id="_2-1-运行时硬约束" tabindex="-1">2.1 运行时硬约束 <a class="header-anchor" href="#_2-1-运行时硬约束" aria-label="Permalink to &quot;2.1 运行时硬约束&quot;">​</a></h3><ul><li>所需 Node.js API、原生扩展和第三方 SDK 必须被目标运行时支持；</li><li>数据驻留、日志传输和密钥管理必须符合区域要求；</li><li>私有网络、数据库连接和身份系统必须可达；</li><li>超时、响应体、内存和并发限制能够覆盖真实工作负载；</li><li>平台故障时有可执行的回滚或转移方案。</li></ul><h3 id="_2-2-评价维度" tabindex="-1">2.2 评价维度 <a class="header-anchor" href="#_2-2-评价维度" aria-label="Permalink to &quot;2.2 评价维度&quot;">​</a></h3><p>比较全球延迟、数据源距离、冷启动、运行时兼容、状态和连接、扩缩容、可观测性、单位成本、供应商锁定和运维责任。必须测量完整请求路径，而不是只测函数执行时间。</p><h2 id="_3-候选运行形态" tabindex="-1">3. 候选运行形态 <a class="header-anchor" href="#_3-候选运行形态" aria-label="Permalink to &quot;3. 候选运行形态&quot;">​</a></h2><h3 id="_3-1-静态托管与-cdn" tabindex="-1">3.1 静态托管与 CDN <a class="header-anchor" href="#_3-1-静态托管与-cdn" aria-label="Permalink to &quot;3.1 静态托管与 CDN&quot;">​</a></h3><p>将 HTML、JavaScript、CSS 和媒体作为不可变制品部署，边缘节点直接缓存。成本低、容量和回滚简单，适合公开静态内容和 CSR 外壳；不能在请求时安全读取私有数据或执行个性化逻辑。</p><h3 id="_3-2-长驻-node-js-服务" tabindex="-1">3.2 长驻 Node.js 服务 <a class="header-anchor" href="#_3-2-长驻-node-js-服务" aria-label="Permalink to &quot;3.2 长驻 Node.js 服务&quot;">​</a></h3><p>进程持续运行，可使用完整 Node.js 生态、连接池、流和较长任务。适合复杂 SSR、BFF、私有网络和稳定流量。团队承担容量、补丁、部署和故障恢复，全球分布通常需要多区域设计。</p><h3 id="_3-3-serverless-node-js-函数" tabindex="-1">3.3 Serverless Node.js 函数 <a class="header-anchor" href="#_3-3-serverless-node-js-函数" aria-label="Permalink to &quot;3.3 Serverless Node.js 函数&quot;">​</a></h3><p>按请求扩缩容，减少常驻容量管理，适合突发或中低流量接口。仍是 Node.js 运行时，但受冷启动、执行时限、连接模型和平台配额影响。高稳定流量下不一定更便宜。</p><h3 id="_3-4-edge-runtime" tabindex="-1">3.4 Edge Runtime <a class="header-anchor" href="#_3-4-edge-runtime" aria-label="Permalink to &quot;3.4 Edge Runtime&quot;">​</a></h3><p>在靠近用户的分布式节点运行受限 Web API 风格代码，适合重定向、鉴权前置、A/B 分流、轻量 HTML 变换和可在边缘缓存的请求。若每次都要访问单区域数据库，额外数据往返可能抵消用户侧距离优势。</p><h2 id="_4-关键维度对比" tabindex="-1">4. 关键维度对比 <a class="header-anchor" href="#_4-关键维度对比" aria-label="Permalink to &quot;4. 关键维度对比&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>静态 CDN</th><th>长驻 Node.js</th><th>Serverless Node.js</th><th>Edge Runtime</th></tr></thead><tbody><tr><td>动态计算</td><td>无</td><td>完整</td><td>完整但有配额</td><td>受限</td></tr><tr><td>Node.js 兼容</td><td>不适用</td><td>最好</td><td>通常较好</td><td>需逐项验证</td></tr><tr><td>全球首跳</td><td>最优</td><td>取决于区域</td><td>取决于区域</td><td>优</td></tr><tr><td>数据库连接</td><td>无</td><td>连接池友好</td><td>需适配弹性连接</td><td>常受数据距离限制</td></tr><tr><td>长连接与流</td><td>静态传输</td><td>可控</td><td>依平台</td><td>依平台限制</td></tr><tr><td>运维责任</td><td>最低</td><td>最高</td><td>中</td><td>中</td></tr><tr><td>锁定风险</td><td>低</td><td>低至中</td><td>中</td><td>中至高</td></tr></tbody></table><h2 id="_5-场景化推荐结论" tabindex="-1">5. 场景化推荐结论 <a class="header-anchor" href="#_5-场景化推荐结论" aria-label="Permalink to &quot;5. 场景化推荐结论&quot;">​</a></h2><p>案例：产品面向亚洲和欧洲用户；营销与文档公开；账户页需要读取位于新加坡的主数据库；请求身份判断可由签名 Cookie 完成；团队只有两名服务端值班工程师。</p><p>推荐组合部署：</p><ul><li>营销、文档和静态资源部署到 CDN；</li><li>Edge 只负责地区重定向、实验分流和缓存键标准化，不访问主数据库；</li><li>账户 SSR 与 BFF 运行在新加坡的 Serverless Node.js，靠近数据源并使用托管数据库代理；</li><li>若稳定流量使函数成本或连接限制越界，再迁移为长驻 Node.js 服务。</li></ul><p>欧洲账户页不强行 Edge SSR，因为每个请求仍需跨洲访问权威数据。应先通过只读副本、区域化数据或缓存改变数据重力，再重新评估计算位置。</p><h2 id="_6-引入后的后果" tabindex="-1">6. 引入后的后果 <a class="header-anchor" href="#_6-引入后的后果" aria-label="Permalink to &quot;6. 引入后的后果&quot;">​</a></h2><p>组合方案把公开内容成本降到最低，并避免为简单边缘逻辑维护全球 Node 集群。代价是部署目标增多，需要统一追踪、配置、密钥和版本标识。</p><p>Edge 代码应保持小而无状态，Node 服务处理需要 SDK、数据库和复杂流的工作。共享领域代码只能依赖两个运行时都支持的标准能力，否则构建成功不代表运行时兼容。</p><p>退出路径要求核心数据契约不绑定平台专有上下文，静态制品可导出，函数入口通过适配层读取请求和环境变量。</p><h2 id="_7-不适用场景" tabindex="-1">7. 不适用场景 <a class="header-anchor" href="#_7-不适用场景" aria-label="Permalink to &quot;7. 不适用场景&quot;">​</a></h2><ul><li>用户和数据位于同一区域时，Edge 未必带来可测收益。</li><li>依赖原生 Node 模块、长任务、TCP 连接或大型 SDK 时，应先验证 Edge 支持。</li><li>持续高负载不应只按“按调用计费”假设更便宜。</li><li>不要在多个运行环境中复制授权和业务规则。</li><li>静态托管不能承载私有请求时计算，但可以托管私有应用的公共外壳。</li></ul><h2 id="_8-填写完成的决策记录" tabindex="-1">8. 填写完成的决策记录 <a class="header-anchor" href="#_8-填写完成的决策记录" aria-label="Permalink to &quot;8. 填写完成的决策记录&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>内容</th></tr></thead><tbody><tr><td>问题</td><td>全球 Web 应用的静态内容、边缘逻辑和账户 SSR 在哪里运行</td></tr><tr><td>硬约束</td><td>数据驻留新加坡；完整 Node SDK；两人值班；欧洲公开页低延迟</td></tr><tr><td>候选</td><td>全静态、中心 Node、Serverless Node、全 Edge、组合部署</td></tr><tr><td>决定</td><td>CDN + 轻量 Edge + 新加坡 Serverless Node</td></tr><tr><td>关键证据</td><td>数据往返测试、SDK 兼容清单、三个月流量和成本模拟</td></tr><tr><td>接受代价</td><td>三类部署目标；统一追踪和配置更复杂</td></tr><tr><td>明确不做</td><td>Edge 直连主数据库；多区域写入</td></tr><tr><td>退出路径</td><td>标准 Request/Response 适配层；可导出静态制品；无平台数据库绑定</td></tr></tbody></table><h2 id="_9-复查条件" tabindex="-1">9. 复查条件 <a class="header-anchor" href="#_9-复查条件" aria-label="Permalink to &quot;9. 复查条件&quot;">​</a></h2><p>当账户流量稳定后函数费用高于长驻服务 20%、冷启动使 P95 越过预算、数据库完成区域化、Edge 开始支持当前关键依赖，或平台配额和合同变化时复查。任何迁移都应先用相同流量回放测完整端到端路径。</p>',37)])])}const p=e(i,[["render",o]]);export{_ as __pageData,p as default};
